import type { CardInfo, Deck, FormatData, FormatId, Season, SeasonWithDecks } from './types'
import { STANDARD_SEASONS } from './standard/seasons'
import { MODERN_SEASONS } from './modern/seasons'

type SeasonFile = { season: string; decks: Deck[] }
type Loader<T> = () => Promise<T>

// Generated by scripts/pipeline/build.py (MTG_FORMAT=...) — one JSON file per season, plus
// the card data. Each format is a separate lazy chunk.
const SOURCES: Partial<Record<FormatId, { seasons: Season[]; decks: Record<string, Loader<SeasonFile>>; cards: Loader<Record<string, CardInfo>> }>> = {
  standard: {
    seasons: STANDARD_SEASONS,
    decks: import.meta.glob<SeasonFile>('./standard/decks/*.json', { import: 'default' }),
    cards: () => import('./standard/cards.json').then((m) => m.default as unknown as Record<string, CardInfo>),
  },
  modern: {
    seasons: MODERN_SEASONS,
    decks: import.meta.glob<SeasonFile>('./modern/decks/*.json', { import: 'default' }),
    cards: () => import('./modern/cards.json').then((m) => m.default as unknown as Record<string, CardInfo>),
  },
}

const cache = new Map<FormatId, Promise<FormatData>>()

async function load(format: FormatId): Promise<FormatData> {
  const src = SOURCES[format]!
  const [files, cards] = await Promise.all([Promise.all(Object.values(src.decks).map((l) => l())), src.cards()])
  const bySeason = new Map(files.map((f) => [f.season, f.decks]))
  const seasons: SeasonWithDecks[] = src.seasons
    .map((s, i) => ({
      ...s,
      end: src.seasons[i + 1]?.start,
      decks: (bySeason.get(s.id) ?? []).slice().sort((a, b) => a.tier - b.tier || b.stats.share - a.stats.share),
    }))
    .filter((s) => s.decks.length > 0)
  return { seasons, cards }
}

export function loadFormat(format: FormatId): Promise<FormatData> | null {
  if (!SOURCES[format]) return null
  if (!cache.has(format)) cache.set(format, load(format))
  return cache.get(format)!
}

export function findDeck(data: FormatData, id: string): { deck: Deck; season: SeasonWithDecks } | undefined {
  for (const season of data.seasons) {
    const deck = season.decks.find((d) => d.id === id)
    if (deck) return { deck, season }
  }
  return undefined
}
